/**
 * 给外部宿主（本项目 Electron 前端）用的**播放器嵌入入口**。
 *
 * 这里不搬 Re_ADOJAS 的 React/Tailwind 外壳，只把它的渲染引擎（`lib/Player`）包一层
 * 最小 API：给一个容器 + 一份 `.adofai` 文本 + 一个音频 URL，就能播。
 *
 * 载入路径与它自己的 `useFileHandlers.ts` 一致：
 *   new ADOFAI.Level(text, Parsers.StringParser) --'load'--> new Player(loadedLevel)
 *
 * 宿主只需要：createPreview() → 拿到句柄 → startPlay / seekTo / selectTile / destroy。
 * Player 自己内部跑 rAF 循环（updatePlayer + renderPlayer），宿主不用管渲染。
 */
import * as ADOFAI from 'adofai'
import { Parsers } from 'adofai'
import { Player } from './lib/Player/Player'

export interface PreviewOptions {
  /** 编辑器模式：不判定、不失败，相机跟随（= 官方编辑器里的预览态） */
  editorMode?: boolean
  /** 行星拖尾 */
  trail?: boolean
  /** 渲染后端；Electron 下 webgl 更稳 */
  renderer?: 'webgl' | 'webgpu'
  /** 命中音 */
  hitsound?: boolean
  /** 关闭轨道贴图（纯色更容易看清结构） */
  disableTrackTexture?: boolean
  /** 渲染方式 */
  renderMethod?: 'sync' | 'async'
  /** ★ 音乐播放延迟补偿（ms）——播放器自带的「偏移修正」，独立于谱面 offset */
  musicDelayMs?: number
}

export interface PreviewHandle {
  player: any
  /** 换谱面（文本）与音频；会销毁并重建 Player */
  reload(levelText: string, audioUrl?: string | null, opts?: PreviewOptions): Promise<PreviewHandle>
  startPlay(startAtMs?: number): void
  stop(): void
  pause(): void
  resume(): void
  seekTo(timeMs: number, visualOnly?: boolean): void
  selectTile(index: number, moveCamera?: boolean): void
  deselectTile(): void
  getTileTimeMs(index: number): number
  getTileIndexAtTime(ms: number): number
  get tileCount(): number
  get totalDurationMs(): number
  get currentTimeMs(): number
  get isPlaying(): boolean
  get currentTileIndex(): number
  get selectedTileIndex(): number | null
  setZoom(z: number): void
  setEditorMode(on: boolean): void
  /** ★ 偏移修正：音乐播放延迟补偿（ms）。播放中改立即生效。 */
  setMusicDelayMs(ms: number): void
  /** 当前补偿（ms） */
  getMusicDelayMs(): number
  /** 播放器按实测按键误差算出的**建议补偿**（样本 < 5 时返回 null） */
  getSuggestedMusicDelayMs(): number | null
  resize(): void
  destroy(): void
}

function makeHandle(player: any, container: HTMLElement, opts: PreviewOptions): PreviewHandle {
  const handle: PreviewHandle = {
    player,
    async reload(levelText, audioUrl, o2) {
      handle.destroy()
      return createPreview(container, levelText, audioUrl ?? null, o2 ?? opts)
    },
    startPlay: (ms = 0) => player.startPlay(ms),
    stop: () => player.stopPlay(),
    pause: () => player.pausePlay(),
    resume: () => player.resumePlay(),
    seekTo: (ms, visualOnly) => player.seekTo(ms, visualOnly),
    selectTile: (i, moveCamera = true) => player.selectTile(i, moveCamera),
    deselectTile: () => player.deselectTile(),
    getTileTimeMs: (i) => player.getTileTimeMs(i),
    getTileIndexAtTime: (ms) => player.getTileIndexAtTime(ms),
    get tileCount() { return player.tileCount ?? 0 },
    get totalDurationMs() { return player.totalDurationMs ?? 0 },
    get currentTimeMs() { return player.currentTimeMs ?? 0 },
    get isPlaying() { return !!player.isPlayerPlaying },
    get currentTileIndex() { return player.currentTileIndex ?? 0 },
    get selectedTileIndex() { return player.selectedTileIndex ?? null },
    setZoom: (z) => player.setZoom(z),
    setEditorMode: (on) => player.setEditorMode(on),
    // ★ 「偏移修正」：播放器自带的音乐延迟补偿。宿主以前完全没接，
    //   等于把它的校准能力白扔了（这就是本项目关心的「偏移修正」）。幂等：值没变就直接返回。
    setMusicDelayMs: (ms) => {
      try { player.setMusicDelayMs(Math.round(Number(ms) || 0)) } catch { /* 未就绪时忽略 */ }
    },
    getMusicDelayMs: () => {
      try { return Number(player.getMusicDelayMs?.() ?? 0) } catch { return 0 }
    },
    getSuggestedMusicDelayMs: () => {
      try {
        const v = player.getSuggestedAudioDelayMs?.()
        return (v === null || v === undefined) ? null : Number(v)
      } catch { return null }
    },
    resize: () => { try { player.onWindowResize() } catch { /* 未就绪时忽略 */ } },
    destroy: () => {
      try { player.destroyPlayer() } catch { /* 幂等 */ }
      container.innerHTML = ''
    },
  }
  return handle
}

/** 把一份 `.adofai` 文本挂到 `container` 上播放。 */
export function createPreview(
  container: HTMLElement,
  levelText: string,
  audioUrl: string | null = null,
  opts: PreviewOptions = {},
): Promise<PreviewHandle> {
  const {
    editorMode = true,
    trail = true,
    renderer = 'webgl',
    hitsound = false,
    disableTrackTexture = true,
    renderMethod = 'sync',
    musicDelayMs = 0,
  } = opts

  return new Promise((resolve, reject) => {
    let settled = false
    const parser = new Parsers.StringParser()
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const level = new (ADOFAI as any).Level(levelText, parser)

    const timer = setTimeout(() => {
      if (settled) return
      settled = true
      reject(new Error('ADOFAI 播放器：解析谱面超时（30s）'))
    }, 30000)

    level.on('parse:progress', () => { /* 宿主不需要进度条 */ })
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    level.on('load', (loadedLevel: any) => {      if (settled) return
      settled = true
      clearTimeout(timer)
      try {
        container.innerHTML = ''
        const player = new Player(loadedLevel, renderer)
        player.createPlayer(container)
        player.setRenderer(renderer)
        player.setRenderMethod(renderMethod)
        player.setShowTrail(trail)
        player.setHitsoundEnabled(hitsound)
        player.setDisableTrackTexture(disableTrackTexture)
        player.setStatsPanel(false)
        player.setEditorMode(editorMode)
        if (musicDelayMs) player.setMusicDelayMs(Math.round(musicDelayMs))
        if (audioUrl) player.loadMusic(audioUrl)
        resolve(makeHandle(player, container, opts))
      } catch (e) {
        reject(e)
      }
    })

    // ★ 与它自己的 `useFileHandlers.ts:201` 一致：**注册完监听必须显式 load()**，
    //   少了这一句 Level 永远不会发 'load' 事件（表现是静默超时）。
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    ;(level as any).load()
  })
}
